INSERT INTO monster VALUES (557,'Skeleton','Troll Skeleton',NULL,'Large','Undead',NULL,'6d12 (39 hp)','+7','30 ft. (6 squares)','14 (+3 Dex, -1 size, +2 natural), touch 12, flat-footed 11','+3','+13','Claw +8 melee (1d6+6)','2 claws +8 melee (1d6+6) and bite +3 melee (1d6+3)','10 ft.','10 ft','-','Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, undead traits','Fort +2, Ref +5, Will +5','Str 23, Dex 16, Con -, Int -, Wis 10, Cha 1',NULL,NULL,'Improved Initiative',NULL,'Cold mountains','Any','3','None','Always neutral evil','-','-','','Troll skeleton; CR 3; Large undead; HD 6d12; hp 39; Init +7; Spd 30 ft. (6 squares); AC 14 (+3 dex, -1 size, +2 natural), touch 12, flat-footed 11; Base Atk +3; Grp +13; Atk +8 melee (1d6+6, claw); Full Atk +8 melee (1d6+6, 2 claws) and +3 melee (1d6+3, bite); Space/Reach 10 ft./10 ft; SA -; SQ Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, undead traits; AL NE; SV Fort +2, Ref +5, Will +5; Str 23, Dex 16, Con -, Int -, Wis 10, Cha 1\n\nSkills and Feats: ; Improved Initiative','\n      <div topic=\"Creating A Skeleton\" level=\"3\"><p><h3>Creating A Skeleton</h3></p><p>\'Skeleton\' is an acquired template that can be added to any corporeal creature (other than an undead) that has a skeletal system (referred to hereafter as the base creature).</p><div topic=\"Size and Type\" level=\"8\"><p><b>Size and Type:</b> The creature\'s type changes to undead. It retains any subtype except for alignment subtypes (such as good) and subtypes that indicate kind. It does not gain the augmented subtype. It uses all the base creature\'s statistics and special abilities except as noted here.</p>\n</div><div topic=\"Hit Dice\" level=\"8\"><p><b>Hit Dice:</b> Drop any Hit Dice gained from class levels (to a minimum of 1) and raise remaining Hit Dice to d12s. If the creature has more than 20 Hit Dice, it can\'t be made into a skeleton by the <i>animate dead</i> spell.</p>\n</div><div topic=\"Speed\" level=\"8\"><p><b>Speed:</b> Winged skeletons can\'t use their wings to fly. If the base creature flew magically, so can the skeleton.</p>\n</div><div topic=\"Armor Class\" level=\"8\"><p><b>Armor Class:</b> Natural armor bonus changes to a number based on the skeleton\'s size:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny or smaller<br/></td> <td>+0<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium or Large<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>+6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>+10<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Attacks\" level=\"8\"><p><b>Attacks:</b> A skeleton retains all the natural weapons, manufactured weapon attacks, and weapon proficiencies of the base creature, except for attacks that can\'t work without flesh. A creature with hands gains one claw attack per hand; the skeleton can strike with each of its claw attacks at its full attack bonus. A skeleton\'s base attack bonus is equal to 1/2 its Hit Dice.</p>\n</div><div topic=\"Damage\" level=\"8\"><p><b>Damage:</b> Natural and manufactured weapons deal damage normally. A claw attack deals damage depending on the skeleton\'s size. (If the base creature already had claw attacks with its hands, use the skeleton claw damage only if it\'s better.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Diminutive or Fine<br/></td>\n<td>1<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny<br/></td>\n<td>1d2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>1d3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>1d4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>1d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>1d8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>2d6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>2d8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Special Attacks\" level=\"8\"><p><b>Special Attacks:</b> A skeleton retains none of the base creature\'s special attacks.</p>\n</div><div topic=\"Special Qualities\" level=\"8\"><p><b>Special Qualities:</b> A skeleton loses most special qualities of the base creature. It retains any extraordinary special qualities that improve its melee or ranged attacks. A skeleton gains the following special qualities.</p><p><i>Immunity to Cold (Ex):</i> Skeletons are not affected by cold.</p><p><i>Damage Reduction 5/Bludgeoning:</i> Skeletons lack flesh or internal organs.</p>\n</div><div topic=\"Saves\" level=\"8\"><p><b>Saves:</b> Base save bonuses are Fort +1/3 HD, Ref +1/3 HD, and Will +1/2 HD + 2.</p>\n</div><div topic=\"Abilities\" level=\"8\"><p><b>Abilities:</b> A skeleton\'s Dexterity increases by +2, it has no Constitution or Intelligence score, its Wisdom changes to 10, and its Charisma changes to 1.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A skeleton has no skills.</p>\n</div><div topic=\"Feats\" level=\"8\"><p><b>Feats:</b> A skeleton loses all feats of the base creature and gains Improved Initiative.</p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment</b>: Any, usually same as base creature.</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Any.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Depends on Hit Dice, as follows:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice</b><br/></td> <td><b>Challenge Rating</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1/2<br/></td>\n<td>1/6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>1/3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2-3<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4-5<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6-7<br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8-9<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10-11<br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12-14<br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15-17<br/></td>\n<td>7<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18-20<br/></td>\n<td>8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> None.</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always neutral evil.</p>\n</div><div topic=\"Advancement\" level=\"8\"><p><b>Advancement:</b> As base creature (or - if the base creature advances by character class).</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> -.</p><p/><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Troll Skeleton</b><br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Undead<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>6d12 (39 hp)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+7<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (+3 Dex, -1 size, +2 natural), touch 12, flat-footed 11<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+3/+13<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +8 melee (1d6+6)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 claws +8 melee (1d6+6) and bite +3 melee (1d6+3)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./10 ft<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, undead traits<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +2, Ref +5, Will +5<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 23, Dex 16, Con -, Int -, Wis 10, Cha 1<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Improved Initiative<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Cold mountains<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Any<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral evil<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n</table><p/><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (558,'Skeleton','Chimera Skeleton',NULL,'Large','Undead',NULL,'9d12 (58 hp)','+6','30 ft. (6 squares)','13 (+2 Dex., -1 size, +2 natural), touch 11, flat-footed 11','+4','+12','Bite +7 melee (2d6+4)','Bite +7 melee (2d6+4) and bite+7 melee (1d8+4) and gore +7 melee (1d8+4) and 2 claws +2 melee (1d6+2)','10 ft.','5 ft','-','Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, undead traits','Fort +3, Ref +5, Will +6','Str 19, Dex 15, Con -, Int -, Wis 10, Cha 1',NULL,NULL,'Improved Initiative',NULL,'Temperate hills','Any','4','None','Always neutral evil','10-13 HD (Large); 14-27 HD (Huge)','-','','Chimera skeleton; CR 4; Large undead; HD 9d12; hp 58; Init +6; Spd 30 ft. (6 squares); AC 13 (+2 dex., -1 size, +2 natural), touch 11, flat-footed 11; Base Atk +4; Grp +12; Atk +7 melee (2d6+4, bite); Full Atk +7 melee (2d6+4, bite) and +7 melee (1d8+4, bite) and +7 melee (1d8+4, gore) and +2 melee (1d6+2, 2 claws); Space/Reach 10 ft./5 ft; SA -; SQ Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, undead traits; AL NE; SV Fort +3, Ref +5, Will +6; Str 19, Dex 15, Con -, Int -, Wis 10, Cha 1\n\nSkills and Feats: ; Improved Initiative','\n      <div topic=\"Creating A Skeleton\" level=\"3\"><p><h3>Creating A Skeleton</h3></p><p>\'Skeleton\' is an acquired template that can be added to any corporeal creature (other than an undead) that has a skeletal system (referred to hereafter as the base creature).</p><div topic=\"Size and Type\" level=\"8\"><p><b>Size and Type:</b> The creature\'s type changes to undead. It retains any subtype except for alignment subtypes (such as good) and subtypes that indicate kind. It does not gain the augmented subtype. It uses all the base creature\'s statistics and special abilities except as noted here.</p>\n</div><div topic=\"Hit Dice\" level=\"8\"><p><b>Hit Dice:</b> Drop any Hit Dice gained from class levels (to a minimum of 1) and raise remaining Hit Dice to d12s. If the creature has more than 20 Hit Dice, it can\'t be made into a skeleton by the <i>animate dead</i> spell.</p>\n</div><div topic=\"Speed\" level=\"8\"><p><b>Speed:</b> Winged skeletons can\'t use their wings to fly. If the base creature flew magically, so can the skeleton.</p>\n</div><div topic=\"Armor Class\" level=\"8\"><p><b>Armor Class:</b> Natural armor bonus changes to a number based on the skeleton\'s size:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny or smaller<br/></td> <td>+0<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium or Large<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>+6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>+10<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Attacks\" level=\"8\"><p><b>Attacks:</b> A skeleton retains all the natural weapons, manufactured weapon attacks, and weapon proficiencies of the base creature, except for attacks that can\'t work without flesh. A creature with hands gains one claw attack per hand; the skeleton can strike with each of its claw attacks at its full attack bonus. A skeleton\'s base attack bonus is equal to 1/2 its Hit Dice.</p>\n</div><div topic=\"Damage\" level=\"8\"><p><b>Damage:</b> Natural and manufactured weapons deal damage normally. A claw attack deals damage depending on the skeleton\'s size. (If the base creature already had claw attacks with its hands, use the skeleton claw damage only if it\'s better.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Diminutive or Fine<br/></td>\n<td>1<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny<br/></td>\n<td>1d2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>1d3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>1d4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>1d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>1d8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>2d6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>2d8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Special Attacks\" level=\"8\"><p><b>Special Attacks:</b> A skeleton retains none of the base creature\'s special attacks.</p>\n</div><div topic=\"Special Qualities\" level=\"8\"><p><b>Special Qualities:</b> A skeleton loses most special qualities of the base creature. It retains any extraordinary special qualities that improve its melee or ranged attacks. A skeleton gains the following special qualities.</p><p><i>Immunity to Cold (Ex):</i> Skeletons are not affected by cold.</p><p><i>Damage Reduction 5/Bludgeoning:</i> Skeletons lack flesh or internal organs.</p>\n</div><div topic=\"Saves\" level=\"8\"><p><b>Saves:</b> Base save bonuses are Fort +1/3 HD, Ref +1/3 HD, and Will +1/2 HD + 2.</p>\n</div><div topic=\"Abilities\" level=\"8\"><p><b>Abilities:</b> A skeleton\'s Dexterity increases by +2, it has no Constitution or Intelligence score, its Wisdom changes to 10, and its Charisma changes to 1.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A skeleton has no skills.</p>\n</div><div topic=\"Feats\" level=\"8\"><p><b>Feats:</b> A skeleton loses all feats of the base creature and gains Improved Initiative.</p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment</b>: Any, usually same as base creature.</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Any.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Depends on Hit Dice, as follows:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice</b><br/></td> <td><b>Challenge Rating</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1/2<br/></td>\n<td>1/6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>1/3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2-3<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4-5<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6-7<br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8-9<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10-11<br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12-14<br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15-17<br/></td>\n<td>7<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18-20<br/></td>\n<td>8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> None.</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always neutral evil.</p>\n</div><div topic=\"Advancement\" level=\"8\"><p><b>Advancement:</b> As base creature (or - if the base creature advances by character class).</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> -.</p><p/><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td><b>Chimera Skeleton</b><br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Large Undead<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>9d12 (58 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>+6<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>30 ft. (6 squares)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>13 (+2 Dex., -1 size, +2 natural), touch 11, flat-footed 11<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+4/+12<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Bite +7 melee (2d6+4)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td>Bite +7 melee (2d6+4) and bite+7 melee (1d8+4) and gore +7 melee (1d8+4) and 2 claws +2 melee (1d6+2)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>10 ft./5 ft<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, undead traits<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +3, Ref +5, Will +6<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 19, Dex 15, Con -, Int -, Wis 10, Cha 1<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Improved Initiative<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n<td>Temperate hills<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Any<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>4<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>None<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Always neutral evil<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>10-13 HD (Large); 14-27 HD (Huge)<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n</table><p/><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (559,'Skeleton','Ettin Skeleton',NULL,'Large','Undead',NULL,'10d12 (65 hp)','+4','40 ft. (8 squares)','11 (-1 size, +2 natural), touch 9, flat-footed 11','+5','+15','Morningstar +10 melee (2d6+6) or claw +10 melee (1d6+6) or javelin +4 ranged (1d8+6)','2 morningstars +10 melee (2d6+6) or 2 claws +10 melee (1d6+6) or 2 javelins +4 ranged (1d8+6)','10 ft.','10 ft.','-','Damage reduction 5/bludgeoning, darkvision 60 ft., darkvision 60 ft., immunity to cold, superior twoweapon','Fort +3, Ref +3, Will +7','Str 23, Dex 10, Con -, Int -, Wis 10, Cha 1',NULL,NULL,'Improved Initiative',NULL,'Cold hills','Any','5','None','Always neutral evil','-','-','','Ettin skeleton; CR 5; Large undead; HD 10d12; hp 65; Init +4; Spd 40 ft. (8 squares); AC 11 (-1 size, +2 natural), touch 9, flat-footed 11; Base Atk +5; Grp +15; Atk +10 melee (2d6+6, morningstar) or +10 melee (1d6+6, claw) or +4 ranged (1d8+6, javelin); Full Atk +10 melee (2d6+6, 2 morningstars) or +10 melee (1d6+6, 2 claws) or +4 ranged (1d8+6, 2 javelins); Space/Reach 10 ft./10 ft.; SA -; SQ Damage reduction 5/bludgeoning, darkvision 60 ft., darkvision 60 ft., immunity to cold, superior twoweapon; AL NE; SV Fort +3, Ref +3, Will +7; Str 23, Dex 10, Con -, Int -, Wis 10, Cha 1\n\nSkills and Feats: ; Improved Initiative','\n      <div topic=\"Creating A Skeleton\" level=\"3\"><p><h3>Creating A Skeleton</h3></p><p>\'Skeleton\' is an acquired template that can be added to any corporeal creature (other than an undead) that has a skeletal system (referred to hereafter as the base creature).</p><div topic=\"Size and Type\" level=\"8\"><p><b>Size and Type:</b> The creature\'s type changes to undead. It retains any subtype except for alignment subtypes (such as good) and subtypes that indicate kind. It does not gain the augmented subtype. It uses all the base creature\'s statistics and special abilities except as noted here.</p>\n</div><div topic=\"Hit Dice\" level=\"8\"><p><b>Hit Dice:</b> Drop any Hit Dice gained from class levels (to a minimum of 1) and raise remaining Hit Dice to d12s. If the creature has more than 20 Hit Dice, it can\'t be made into a skeleton by the <i>animate dead</i> spell.</p>\n</div><div topic=\"Speed\" level=\"8\"><p><b>Speed:</b> Winged skeletons can\'t use their wings to fly. If the base creature flew magically, so can the skeleton.</p>\n</div><div topic=\"Armor Class\" level=\"8\"><p><b>Armor Class:</b> Natural armor bonus changes to a number based on the skeleton\'s size:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny or smaller<br/></td> <td>+0<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium or Large<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>+6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>+10<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Attacks\" level=\"8\"><p><b>Attacks:</b> A skeleton retains all the natural weapons, manufactured weapon attacks, and weapon proficiencies of the base creature, except for attacks that can\'t work without flesh. A creature with hands gains one claw attack per hand; the skeleton can strike with each of its claw attacks at its full attack bonus. A skeleton\'s base attack bonus is equal to 1/2 its Hit Dice.</p>\n</div><div topic=\"Damage\" level=\"8\"><p><b>Damage:</b> Natural and manufactured weapons deal damage normally. A claw attack deals damage depending on the skeleton\'s size. (If the base creature already had claw attacks with its hands, use the skeleton claw damage only if it\'s better.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Diminutive or Fine<br/></td>\n<td>1<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny<br/></td>\n<td>1d2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>1d3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>1d4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>1d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>1d8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>2d6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>2d8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Special Attacks\" level=\"8\"><p><b>Special Attacks:</b> A skeleton retains none of the base creature\'s special attacks.</p>\n</div><div topic=\"Special Qualities\" level=\"8\"><p><b>Special Qualities:</b> A skeleton loses most special qualities of the base creature. It retains any extraordinary special qualities that improve its melee or ranged attacks. A skeleton gains the following special qualities.</p><p><i>Immunity to Cold (Ex):</i> Skeletons are not affected by cold.</p><p><i>Damage Reduction 5/Bludgeoning:</i> Skeletons lack flesh or internal organs.</p>\n</div><div topic=\"Saves\" level=\"8\"><p><b>Saves:</b> Base save bonuses are Fort +1/3 HD, Ref +1/3 HD, and Will +1/2 HD + 2.</p>\n</div><div topic=\"Abilities\" level=\"8\"><p><b>Abilities:</b> A skeleton\'s Dexterity increases by +2, it has no Constitution or Intelligence score, its Wisdom changes to 10, and its Charisma changes to 1.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A skeleton has no skills.</p>\n</div><div topic=\"Feats\" level=\"8\"><p><b>Feats:</b> A skeleton loses all feats of the base creature and gains Improved Initiative.</p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment</b>: Any, usually same as base creature.</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Any.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Depends on Hit Dice, as follows:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice</b><br/></td> <td><b>Challenge Rating</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1/2<br/></td>\n<td>1/6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>1/3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2-3<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4-5<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6-7<br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8-9<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10-11<br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12-14<br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15-17<br/></td>\n<td>7<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18-20<br/></td>\n<td>8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> None.</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always neutral evil.</p>\n</div><div topic=\"Advancement\" level=\"8\"><p><b>Advancement:</b> As base creature (or - if the base creature advances by character class).</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> -.</p><p/><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td><b>Ettin Skeleton</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td>Large Undead<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n\n<td>10d12 (65 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n\n<td>11 (-1 size, +2 natural), touch 9, flat-footed 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n\n<td>+5/+15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n\n<td>Morningstar +10 melee (2d6+6) or claw +10 melee (1d6+6) or javelin +4 ranged (1d8+6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n\n<td>2 morningstars +10 melee (2d6+6) or 2 claws +10 melee (1d6+6) or 2 javelins +4 ranged (1d8+6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n\n<td>Damage reduction 5/bludgeoning, darkvision 60 ft., darkvision 60 ft., immunity to cold, superior twoweapon<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n\n<td>Fort +3, Ref +3, Will +7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n\n<td>Str 23, Dex 10, Con -, Int -, Wis 10, Cha 1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n\n<td>Improved Initiative<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n\n<td>Cold hills<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n\n<td>Always neutral evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n\n<td>-<br/></td>\n\n</tr>\n</table><p/><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (560,'Skeleton','Advanced Megaraptor Skeleton',NULL,'Huge','Undead',NULL,'12d12 (78 hp)','+7','60 ft. (12 squares)','14 (-2 size, +3 Dex, +3 natural), touch 11, flat-footed 11','+6','+19','Talons +9 melee (2d8+5)','Talons +9 melee (2d8+5) and 2 claws +4 melee (1d8+2) and bite +4 melee (2d6+2)','15 ft.','10 ft.','-','Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, undead traits','Fort +4, Ref +7, Will +8','Str 21, Dex 17, Con -, Int -, Wis 10, Cha 1',NULL,NULL,'Improved Initiative',NULL,'Warm forests','Any','6','None','Always neutral evil','13-16 HD (Huge); 17-20 HD (Gargantuan)','-','','Advanced megaraptor skeleton; CR 6; Huge undead; HD 12d12; hp 78; Init +7; Spd 60 ft. (12 squares); AC 14 (-2 size, +3 dex, +3 natural), touch 11, flat-footed 11; Base Atk +6; Grp +19; Atk +9 melee (2d8+5, talons); Full Atk +9 melee (2d8+5, talons) and +4 melee (1d8+2, 2 claws) and +4 melee (2d6+2, bite); Space/Reach 15 ft./10 ft.; SA -; SQ Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, undead traits; AL NE; SV Fort +4, Ref +7, Will +8; Str 21, Dex 17, Con -, Int -, Wis 10, Cha 1\n\nSkills and Feats: ; Improved Initiative','\n      <div topic=\"Creating A Skeleton\" level=\"3\"><p><h3>Creating A Skeleton</h3></p><p>\'Skeleton\' is an acquired template that can be added to any corporeal creature (other than an undead) that has a skeletal system (referred to hereafter as the base creature).</p><div topic=\"Size and Type\" level=\"8\"><p><b>Size and Type:</b> The creature\'s type changes to undead. It retains any subtype except for alignment subtypes (such as good) and subtypes that indicate kind. It does not gain the augmented subtype. It uses all the base creature\'s statistics and special abilities except as noted here.</p>\n</div><div topic=\"Hit Dice\" level=\"8\"><p><b>Hit Dice:</b> Drop any Hit Dice gained from class levels (to a minimum of 1) and raise remaining Hit Dice to d12s. If the creature has more than 20 Hit Dice, it can\'t be made into a skeleton by the <i>animate dead</i> spell.</p>\n</div><div topic=\"Speed\" level=\"8\"><p><b>Speed:</b> Winged skeletons can\'t use their wings to fly. If the base creature flew magically, so can the skeleton.</p>\n</div><div topic=\"Armor Class\" level=\"8\"><p><b>Armor Class:</b> Natural armor bonus changes to a number based on the skeleton\'s size:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny or smaller<br/></td> <td>+0<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium or Large<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>+6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>+10<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Attacks\" level=\"8\"><p><b>Attacks:</b> A skeleton retains all the natural weapons, manufactured weapon attacks, and weapon proficiencies of the base creature, except for attacks that can\'t work without flesh. A creature with hands gains one claw attack per hand; the skeleton can strike with each of its claw attacks at its full attack bonus. A skeleton\'s base attack bonus is equal to 1/2 its Hit Dice.</p>\n</div><div topic=\"Damage\" level=\"8\"><p><b>Damage:</b> Natural and manufactured weapons deal damage normally. A claw attack deals damage depending on the skeleton\'s size. (If the base creature already had claw attacks with its hands, use the skeleton claw damage only if it\'s better.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Diminutive or Fine<br/></td>\n<td>1<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny<br/></td>\n<td>1d2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>1d3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>1d4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>1d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>1d8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>2d6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>2d8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Special Attacks\" level=\"8\"><p><b>Special Attacks:</b> A skeleton retains none of the base creature\'s special attacks.</p>\n</div><div topic=\"Special Qualities\" level=\"8\"><p><b>Special Qualities:</b> A skeleton loses most special qualities of the base creature. It retains any extraordinary special qualities that improve its melee or ranged attacks. A skeleton gains the following special qualities.</p><p><i>Immunity to Cold (Ex):</i> Skeletons are not affected by cold.</p><p><i>Damage Reduction 5/Bludgeoning:</i> Skeletons lack flesh or internal organs.</p>\n</div><div topic=\"Saves\" level=\"8\"><p><b>Saves:</b> Base save bonuses are Fort +1/3 HD, Ref +1/3 HD, and Will +1/2 HD + 2.</p>\n</div><div topic=\"Abilities\" level=\"8\"><p><b>Abilities:</b> A skeleton\'s Dexterity increases by +2, it has no Constitution or Intelligence score, its Wisdom changes to 10, and its Charisma changes to 1.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A skeleton has no skills.</p>\n</div><div topic=\"Feats\" level=\"8\"><p><b>Feats:</b> A skeleton loses all feats of the base creature and gains Improved Initiative.</p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment</b>: Any, usually same as base creature.</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Any.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Depends on Hit Dice, as follows:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice</b><br/></td> <td><b>Challenge Rating</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1/2<br/></td>\n<td>1/6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>1/3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2-3<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4-5<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6-7<br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8-9<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10-11<br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12-14<br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15-17<br/></td>\n<td>7<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18-20<br/></td>\n<td>8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> None.</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always neutral evil.</p>\n</div><div topic=\"Advancement\" level=\"8\"><p><b>Advancement:</b> As base creature (or - if the base creature advances by character class).</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> -.</p><p/><p/><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Advanced Megaraptor Skeleton</b><br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Undead<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>12d12 (78 hp)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+7<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>60 ft. (12 squares)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (-2 size, +3 Dex, +3 natural), touch 11, flat-footed 11<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+6/+19<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Talons +9 melee (2d8+5)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Talons +9 melee (2d8+5) and 2 claws +4 melee (1d8+2) and bite +4 melee (2d6+2)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./10 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, undead traits<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref +7, Will +8<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 21, Dex 17, Con -, Int -, Wis 10, Cha 1<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Improved Initiative<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm forests<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Any<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>6<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral evil<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>13-16 HD (Huge); 17-20 HD (Gargantuan)<br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n</table><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (561,'Skeleton','Cloud Giant Skeleton',NULL,'Huge','Undead',NULL,'17d12 (110 hp)','+6','50 ft. (10 squares)','13 (-2 size, +2 Dex, +3 natural), touch 10, flat-footed 11','+8','+28','Gargantuan morningstar +18 melee (4d6+18) or claw +18 melee (1d8+12) or rock +8 ranged (2d8+12)','Gargantuan morningstar +18/+13 melee (4d6+18) or 2 claws +18 melee (1d8+12) or rock +8 ranged (2d8+12)','15 ft.','15 ft.','-','Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, oversize weapon, undead traits','Fort +5, Ref +7, Will +10','Str 35, Dex 15, Con -, Int -, Wis 10, Cha 1',NULL,NULL,'Improved Initiative',NULL,'Temperate mountains','Any','7','None','Always neutral evil','-','-','','Cloud giant skeleton; CR 7; Huge undead; HD 17d12; hp 110; Init +6; Spd 50 ft. (10 squares); AC 13 (-2 size, +2 dex, +3 natural), touch 10, flat-footed 11; Base Atk +8; Grp +28; Atk +18 melee (4d6+18, gargantuan morningstar) or +18 melee (1d8+12, claw) or +8 ranged (2d8+12, rock); Full Atk +18 /+13 melee (4d6+18, gargantuan morningstar) or +18 melee (1d8+12, 2 claws) or +8 ranged (2d8+12, rock); Space/Reach 15 ft./15 ft.; SA -; SQ Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, oversize weapon, undead traits; AL NE; SV Fort +5, Ref +7, Will +10; Str 35, Dex 15, Con -, Int -, Wis 10, Cha 1\n\nSkills and Feats: ; Improved Initiative','\n      <div topic=\"Creating A Skeleton\" level=\"3\"><p><h3>Creating A Skeleton</h3></p><p>\'Skeleton\' is an acquired template that can be added to any corporeal creature (other than an undead) that has a skeletal system (referred to hereafter as the base creature).</p><div topic=\"Size and Type\" level=\"8\"><p><b>Size and Type:</b> The creature\'s type changes to undead. It retains any subtype except for alignment subtypes (such as good) and subtypes that indicate kind. It does not gain the augmented subtype. It uses all the base creature\'s statistics and special abilities except as noted here.</p>\n</div><div topic=\"Hit Dice\" level=\"8\"><p><b>Hit Dice:</b> Drop any Hit Dice gained from class levels (to a minimum of 1) and raise remaining Hit Dice to d12s. If the creature has more than 20 Hit Dice, it can\'t be made into a skeleton by the <i>animate dead</i> spell.</p>\n</div><div topic=\"Speed\" level=\"8\"><p><b>Speed:</b> Winged skeletons can\'t use their wings to fly. If the base creature flew magically, so can the skeleton.</p>\n</div><div topic=\"Armor Class\" level=\"8\"><p><b>Armor Class:</b> Natural armor bonus changes to a number based on the skeleton\'s size:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny or smaller<br/></td> <td>+0<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium or Large<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>+6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>+10<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Attacks\" level=\"8\"><p><b>Attacks:</b> A skeleton retains all the natural weapons, manufactured weapon attacks, and weapon proficiencies of the base creature, except for attacks that can\'t work without flesh. A creature with hands gains one claw attack per hand; the skeleton can strike with each of its claw attacks at its full attack bonus. A skeleton\'s base attack bonus is equal to 1/2 its Hit Dice.</p>\n</div><div topic=\"Damage\" level=\"8\"><p><b>Damage:</b> Natural and manufactured weapons deal damage normally. A claw attack deals damage depending on the skeleton\'s size. (If the base creature already had claw attacks with its hands, use the skeleton claw damage only if it\'s better.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Diminutive or Fine<br/></td>\n<td>1<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny<br/></td>\n<td>1d2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>1d3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>1d4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>1d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>1d8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>2d6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>2d8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Special Attacks\" level=\"8\"><p><b>Special Attacks:</b> A skeleton retains none of the base creature\'s special attacks.</p>\n</div><div topic=\"Special Qualities\" level=\"8\"><p><b>Special Qualities:</b> A skeleton loses most special qualities of the base creature. It retains any extraordinary special qualities that improve its melee or ranged attacks. A skeleton gains the following special qualities.</p><p><i>Immunity to Cold (Ex):</i> Skeletons are not affected by cold.</p><p><i>Damage Reduction 5/Bludgeoning:</i> Skeletons lack flesh or internal organs.</p>\n</div><div topic=\"Saves\" level=\"8\"><p><b>Saves:</b> Base save bonuses are Fort +1/3 HD, Ref +1/3 HD, and Will +1/2 HD + 2.</p>\n</div><div topic=\"Abilities\" level=\"8\"><p><b>Abilities:</b> A skeleton\'s Dexterity increases by +2, it has no Constitution or Intelligence score, its Wisdom changes to 10, and its Charisma changes to 1.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A skeleton has no skills.</p>\n</div><div topic=\"Feats\" level=\"8\"><p><b>Feats:</b> A skeleton loses all feats of the base creature and gains Improved Initiative.</p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment</b>: Any, usually same as base creature.</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Any.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Depends on Hit Dice, as follows:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice</b><br/></td> <td><b>Challenge Rating</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1/2<br/></td>\n<td>1/6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>1/3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2-3<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4-5<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6-7<br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8-9<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10-11<br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12-14<br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15-17<br/></td>\n<td>7<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18-20<br/></td>\n<td>8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> None.</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always neutral evil.</p>\n</div><div topic=\"Advancement\" level=\"8\"><p><b>Advancement:</b> As base creature (or - if the base creature advances by character class).</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> -.</p><p/><p/><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td><b>Cloud Giant Skeleton</b><br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Huge Undead<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>17d12 (110 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>+6<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>50 ft. (10 squares)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>13 (-2 size, +2 Dex, +3 natural), touch 10, flat-footed 11<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+8/+28<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Gargantuan morningstar +18 melee (4d6+18) or claw +18 melee (1d8+12) or rock +8 ranged (2d8+12)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td>Gargantuan morningstar +18/+13 melee (4d6+18) or 2 claws +18 melee (1d8+12) or rock +8 ranged (2d8+12)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>15 ft./15 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold, oversize weapon, undead traits<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +5, Ref +7, Will +10<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 35, Dex 15, Con -, Int -, Wis 10, Cha 1<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Improved Initiative<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n<td>Temperate mountains<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Any<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>7<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>None<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Always neutral evil<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n</table><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (562,'Skeleton','Young Adult Red Dragon Skeleton',NULL,'Huge','Undead','Fire','19d12 (123 hp)','+5','40 ft. (8 squares)','12 (-2 size, +1 Dex, +3 natural), touch 9, flat-footed 11','+9','+27','Bite +17 melee (2d8+10)','Bite +17 melee (2d8+10) and 2 claws +12 melee (2d6+5) and 2 wings +12 melee (1d8+5) and tail slap +12 melee (2d6+15)','15 ft.','10 ft.','-','Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, undead traits','Fort +6, Ref +7, Will +8','Str 31, Dex 12, Con -, Int -, Wis 10, Cha 1',NULL,NULL,'Improved Initiative',NULL,'Warm mountains','Any','8','None','Always neutral evil','20 HD (Huge)','-','','Young adult red dragon skeleton; CR 8; Huge undead (fire); HD 19d12; hp 123; Init +5; Spd 40 ft. (8 squares); AC 12 (-2 size, +1 dex, +3 natural), touch 9, flat-footed 11; Base Atk +9; Grp +27; Atk +17 melee (2d8+10, bite); Full Atk +17 melee (2d8+10, bite) and +12 melee (2d6+5, 2 claws) and +12 melee (1d8+5, 2 wings) and +12 melee (2d6+15, tail slap); Space/Reach 15 ft./10 ft.; SA -; SQ Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, undead traits; AL NE; SV Fort +6, Ref +7, Will +8; Str 31, Dex 12, Con -, Int -, Wis 10, Cha 1\n\nSkills and Feats: ; Improved Initiative','\n      <div topic=\"Creating A Skeleton\" level=\"3\"><p><h3>Creating A Skeleton</h3></p><p>\'Skeleton\' is an acquired template that can be added to any corporeal creature (other than an undead) that has a skeletal system (referred to hereafter as the base creature).</p><div topic=\"Size and Type\" level=\"8\"><p><b>Size and Type:</b> The creature\'s type changes to undead. It retains any subtype except for alignment subtypes (such as good) and subtypes that indicate kind. It does not gain the augmented subtype. It uses all the base creature\'s statistics and special abilities except as noted here.</p>\n</div><div topic=\"Hit Dice\" level=\"8\"><p><b>Hit Dice:</b> Drop any Hit Dice gained from class levels (to a minimum of 1) and raise remaining Hit Dice to d12s. If the creature has more than 20 Hit Dice, it can\'t be made into a skeleton by the <i>animate dead</i> spell.</p>\n</div><div topic=\"Speed\" level=\"8\"><p><b>Speed:</b> Winged skeletons can\'t use their wings to fly. If the base creature flew magically, so can the skeleton.</p>\n</div><div topic=\"Armor Class\" level=\"8\"><p><b>Armor Class:</b> Natural armor bonus changes to a number based on the skeleton\'s size:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny or smaller<br/></td> <td>+0<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium or Large<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>+6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>+10<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Attacks\" level=\"8\"><p><b>Attacks:</b> A skeleton retains all the natural weapons, manufactured weapon attacks, and weapon proficiencies of the base creature, except for attacks that can\'t work without flesh. A creature with hands gains one claw attack per hand; the skeleton can strike with each of its claw attacks at its full attack bonus. A skeleton\'s base attack bonus is equal to 1/2 its Hit Dice.</p>\n</div><div topic=\"Damage\" level=\"8\"><p><b>Damage:</b> Natural and manufactured weapons deal damage normally. A claw attack deals damage depending on the skeleton\'s size. (If the base creature already had claw attacks with its hands, use the skeleton claw damage only if it\'s better.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Diminutive or Fine<br/></td>\n<td>1<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny<br/></td>\n<td>1d2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>1d3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>1d4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>1d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>1d8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>2d6<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>2d8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Special Attacks\" level=\"8\"><p><b>Special Attacks:</b> A skeleton retains none of the base creature\'s special attacks.</p>\n</div><div topic=\"Special Qualities\" level=\"8\"><p><b>Special Qualities:</b> A skeleton loses most special qualities of the base creature. It retains any extraordinary special qualities that improve its melee or ranged attacks. A skeleton gains the following special qualities.</p><p><i>Immunity to Cold (Ex):</i> Skeletons are not affected by cold.</p><p><i>Damage Reduction 5/Bludgeoning:</i> Skeletons lack flesh or internal organs.</p>\n</div><div topic=\"Saves\" level=\"8\"><p><b>Saves:</b> Base save bonuses are Fort +1/3 HD, Ref +1/3 HD, and Will +1/2 HD + 2.</p>\n</div><div topic=\"Abilities\" level=\"8\"><p><b>Abilities:</b> A skeleton\'s Dexterity increases by +2, it has no Constitution or Intelligence score, its Wisdom changes to 10, and its Charisma changes to 1.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A skeleton has no skills.</p>\n</div><div topic=\"Feats\" level=\"8\"><p><b>Feats:</b> A skeleton loses all feats of the base creature and gains Improved Initiative.</p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment</b>: Any, usually same as base creature.</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Any.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Depends on Hit Dice, as follows:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice</b><br/></td> <td><b>Challenge Rating</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1/2<br/></td>\n<td>1/6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>1/3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2-3<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4-5<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6-7<br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8-9<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10-11<br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12-14<br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15-17<br/></td>\n<td>7<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18-20<br/></td>\n<td>8<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> None.</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always neutral evil.</p>\n</div><div topic=\"Advancement\" level=\"8\"><p><b>Advancement:</b> As base creature (or - if the base creature advances by character class).</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> -.</p><p/><p/><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td><b>Young Adult Red Dragon Skeleton</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td>Huge Undead (Fire)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n\n<td>19d12 (123 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n\n<td>12 (-2 size, +1 Dex, +3 natural), touch 9, flat-footed 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n\n<td>+9/+27<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n\n<td>Bite +17 melee (2d8+10)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n\n<td>Bite +17 melee (2d8+10) and 2 claws +12 melee (2d6+5) and 2 wings +12 melee (1d8+5) and tail slap +12 melee (2d6+15)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n\n<td>15 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n\n<td>Damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, undead traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>